(()=>{'use strict';
const $=s=>document.querySelector(s),svgNS='http://www.w3.org/2000/svg',fmt=n=>{for(const [v,u]of [[1e16,'경'],[1e12,'조'],[1e8,'억'],[1e4,'만']])if(n>=v)return(n/v).toLocaleString('ko-KR',{maximumFractionDigits:1})+u;return Number(n).toLocaleString('ko-KR',{maximumFractionDigits:0});},el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};let data,ko={};
function renderTiers(){const host=$('#dashboard-tiers'),rows=[...(data?.modes?.[$('#dashboard-mode').value]?.rows||[])].sort((a,b)=>b.dps-a.dps);host.replaceChildren();if(!rows.length){host.append(el('p','티어 데이터를 불러올 수 없습니다. 잠시 후 다시 확인해 주세요.','empty-message'));return;}const groups=['S','A','B','C','D'].map(()=>[]);CoopDealerTools.tierScores(rows).forEach(r=>groups[['S','A','B','C','D'].indexOf(r.tier)].push(r));groups.forEach((group,i)=>{const row=el('div',undefined,'preview-tier tier-'+i),label=el('div',undefined,'preview-tier-label');label.append(el('b',['S','A','B','C','D'][i]),el('small',['최상','강력','준수','보통','낮음'][i]));const cards=el('div',undefined,'preview-tier-cards');for(const r of group){const d=CoopData.DEMON_BY_SLUG.get(r.slug);if(!d)continue;const card=el('button',undefined,'preview-unit');card.type='button';card.setAttribute('aria-label',(ko[d.name]||d.name)+' 계산 조건 보기');card.onclick=()=>CoopDealerConditions.open(r,$('#dashboard-mode').value,ko);const img=el('img');img.src='/assets/units/'+d.img+'.webp';img.alt='';img.loading='lazy';const text=el('span');text.append(el('b',ko[d.name]||d.name),el('small',fmt(r.dps)+' DPS'));card.append(img,text);cards.append(card);}row.append(label,cards);host.append(row);});}
async function visitors(){const host=$('#dashboard-visitors');try{const r=await fetch('/api/visitors');if(!r.ok)throw Error();const {days}=await r.json();host.replaceChildren();if(!days?.length){host.append(el('p','아직 기록된 방문 데이터가 없습니다.','empty-message'));return;}const svg=document.createElementNS(svgNS,'svg'),width=560,height=220,left=40,right=24,top=28,bottom=32,max=Math.max(4,Math.ceil(Math.max(...days.map(d=>d.visitors))/4)*4),x=i=>days.length===1?width/2:left+i*(width-left-right)/(days.length-1),y=n=>height-bottom-n/max*(height-top-bottom);svg.setAttribute('viewBox','0 0 '+width+' '+height);svg.setAttribute('role','img');svg.setAttribute('aria-label','최근 1주일 일별 방문자');const add=(tag,attrs,text)=>{const n=document.createElementNS(svgNS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;svg.append(n);return n;};add('desc',{},days.map(d=>d.date+' '+d.visitors+'명').join(', '));for(let i=0;i<=4;i++){add('line',{x1:left,x2:width-right,y1:y(max*i/4),y2:y(max*i/4),class:'visitor-grid'});add('text',{x:left-8,y:y(max*i/4)+4,'text-anchor':'end',class:'visitor-axis'},String(max*i/4));}add('polyline',{points:days.map((d,i)=>x(i)+','+y(d.visitors)).join(' '),class:'visitor-line'});days.forEach((d,i)=>{const dot=add('circle',{cx:x(i),cy:y(d.visitors),r:4,class:'visitor-dot'}),title=document.createElementNS(svgNS,'title');title.textContent=d.date+' · '+d.visitors+'명';dot.append(title);add('text',{x:x(i),y:y(d.visitors)-12,'text-anchor':'middle',class:'visitor-value'},d.visitors.toLocaleString('ko-KR'));add('text',{x:x(i),y:height-8,'text-anchor':'middle',class:'visitor-axis'},d.date.slice(5).replace('-','.'));});host.append(svg);}catch{host.replaceChildren(el('div',undefined,'empty-message'));host.firstChild.append(el('span','통계 서버 연결 대기','empty-title'),el('small','방문 기록이 연결되면 최근 1주일 그래프가 표시됩니다.'));}}
async function ranking(){const list=$('#dashboard-ranking');try{const catalog=await(await fetch('/ranking-catalog.json')).json(),target=catalog.targets.find(t=>t.mode==='deepsea')?.id||catalog.targets.at(-1)?.id,r=await fetch('/api/rankings?'+new URLSearchParams({deck:'clara',target,page:1}));if(!r.ok)throw Error();const json=await r.json(),rows=json.entries||[];list.replaceChildren();if(!rows.length){list.append(el('li','아직 등록된 기록이 없습니다.','empty-message'));return;}rows.slice(0,3).forEach((r,i)=>{const li=el('li'),rank=el('span',String(i+1),'rank-medal');li.append(rank,el('b',r.nickname),el('strong',fmt(r.score)+' DPS'));list.append(li);});}catch{list.replaceChildren(el('li','랭킹 서버 연결 후 실제 기록이 표시됩니다.','empty-message'));}}
$('#dashboard-mode').onchange=renderTiers;Promise.all([fetch('/dealer-rankings.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('/ko.json').then(r=>r.json())]).then(([value,dict])=>{data=value;ko=dict;renderTiers();}).catch(()=>renderTiers());visitors();ranking();
})();
